-- Voorzieningen in een witte kaart, en de eyebrow "De inventaris" eruit.
--
-- Drie wijzigingen op /lodge-de-heide en /lodge-de-eik:
--
-- 1. Het voorzieningenblok staat nu in een witte kaart, zoals het
--    kaartenraster van de kamerindeling erboven. In de data is dat één vlag,
--    marksKaart, op die ene sectie. De huisregels gebruiken hetzelfde
--    marks-blok maar krijgen die vlag NIET: daar horen de pictogrammen bij de
--    lopende tekst en zou een kaart ze juist losweken.
--
-- 2. De eyebrow "De inventaris" boven "Wat er in de lodge zit" is weg.
--
-- 3. De inhoudsopgave ("Op deze pagina") verdwijnt van beide lodgepagina's.
--    Dat zit NIET in deze migratie maar in de code: de template leidt het af
--    uit LODGE_OP_SLUG. Er is dus niets aan de database te doen; de pagina's
--    tonen hem niet meer zodra de deploy live staat.
--
-- Alleen deze twee pagina's, alleen de kolom sections. Ze worden in hun geheel
-- overschreven, want een vlag toevoegen aan één sectie is met replace() niet
-- betrouwbaar te doen.
--
-- VOLGORDE: deze migratie vervangt sections integraal en is daarmee bestand
-- tegen elke eerdere migratie die deze twee pagina's raakt. Draai hem als
-- laatste, dan is de uitkomst hoe dan ook de eindstand.
--
-- Idempotent: een tweede run levert exact dezelfde waarde op.


-- ── lodge-de-heide ──────────────────────────────────────────
update landing_pages
   set sections = '[{"heading": "Wat er in de lodge zit", "body": ["Een lodgepagina zonder concrete inventaris is een foto met een prijs eronder. Daarom hieronder wat er werkelijk in staat, zodat u niet hoeft te mailen om te weten of u een koffiezetapparaat moet meenemen."], "bullets": ["Twee slaapplekken-indelingen: een tweepersoonsbed en een tweede kamer, samen tot vier personen.", "Volledig uitgeruste keuken: oven, kookplaat, koelkast, vaatwasser, servies en pannen.", "Vrij uitzicht over heide en bos vanaf het terras, zonder ander gebouw in beeld.", "Privé-hottub op het afgeschermde terras, het hele jaar door op 38 °C.", "Gratis snel WiFi en gratis parkeren op eigen terrein. Er is een laadstation aanwezig bij de lodge; het laden zelf is niet inbegrepen.", "Digitale sloten: inchecken kan tot middernacht zonder dat iemand op u wacht."]}, {"heading": "Kamerindeling", "body": ["Vier personen past hier zonder te schuiven: twee slaapkamers, elk met een eigen opzet, en een woonkamer waar met z''n vieren aan tafel gegeten kan worden."], "cards": [{"titel": "Slaapkamer 1", "items": [{"icon": "bed", "tekst": "2-persoons bed 1×"}]}, {"titel": "Slaapkamer 2", "items": [{"icon": "bed", "tekst": "1-persoons bed 2×"}]}, {"titel": "Badkamer", "items": [{"icon": "douche", "tekst": "Douche 1×"}, {"icon": "toilet", "tekst": "Toilet 1×"}]}, {"titel": "Woonkamer", "items": [{"icon": "tafel", "tekst": "Eettafel met stoelen"}, {"icon": "tv", "tekst": "TV 1×"}]}, {"titel": "Keuken", "items": [{"icon": "vaatwasser", "tekst": "Afwasmachine 1×"}, {"icon": "koelkast", "tekst": "Koelkast 1×"}, {"icon": "magnetron", "tekst": "Combimagnetron 1×"}, {"icon": "fornuis", "tekst": "Fornuis 1×"}]}], "note": "De lodge is 60 m² en biedt plaats aan maximaal vier personen."}, {"eyebrow": "Voorzieningen", "heading": "Wat er verder aanwezig is", "body": ["De voorzieningen waar gasten het vaakst naar vragen, hier op een rij. Ze zijn in beide lodges gelijk — het verschil tussen De Heide en De Eik zit in het uitzicht en de buitensauna, niet in wat er binnen staat."], "marksKaart": true, "marks": [{"icon": "wifi", "tekst": "Gratis snel WiFi"}, {"icon": "tv", "tekst": "Televisie"}, {"icon": "parkeren", "tekst": "Parkeren op eigen terrein"}, {"icon": "koelkast", "tekst": "Koelkast"}, {"icon": "koffie", "tekst": "Koffieapparaat"}, {"icon": "waterkoker", "tekst": "Waterkoker"}, {"icon": "verwarming", "tekst": "Verwarming"}]}, {"eyebrow": "Het onderscheid", "heading": "Het uitzicht en de hottub", "body": ["De hottub staat op beide terrassen; het uitzicht heeft alleen deze lodge. Dat verschil is groter dan het klinkt. Vanaf dit terras kijkt u over heide en bos zonder dat er één gebouw in beeld staat — geen andere lodge, geen schuur, geen weg. Dat is wat een terras van een uitzicht onderscheidt.", "Alles is volledig privé. Er is op het terrein geen gedeelde wellnessruimte, geen balie waar u langs moet en geen ander gezelschap dat op zijn beurt wacht. Wie hier het terras op stapt, heeft het uitzicht voor zichzelf.", "De hottub hoeft u niet op te warmen: het water staat 24 uur per dag op 38 °C, ook in januari. Juist in de winter, met damp boven het water en kaal bos eromheen, is dat het moment waar gasten achteraf over vertellen."]}, {"eyebrow": "Voor wie", "heading": "Voor wie deze lodge is", "body": ["De Heide is in de eerste plaats een lodge voor twee. Een stel dat een weekend wil waarin niets moet, waar het water en de stilte het programma zijn en de heide het uitzicht. Voor een [romantisch weekend weg in Drenthe](/romantisch-weekend-weg-drenthe) is dit de lodge die het dichtst bij die belofte komt.", "Met vier kan ook: twee stellen, of twee ouders met twee kinderen die groot genoeg zijn om hun eigen kamer te willen. Wilt u vooral samen koken, buiten eten en de sauna in, dan is De Eik de betere keuze — daar staan de buitenkeuken en de buitensauna."]}, {"eyebrow": "Buiten", "heading": "Het uitzicht en het terras", "body": ["Het terras kijkt uit op heide en bos, niet op de andere lodge. Dat is bij het plaatsen zo bedacht: de twee huizen staan op ruime afstand van elkaar en met de terrassen van elkaar af. U ziet vanaf uw eigen stoel geen ander gebouw.", "Vanaf de deur loopt u de Zeijerstrubben in, een oud strubbenbos met kromgegroeide eiken. Het Ballooërveld met zijn schaapskudde ligt op twaalf minuten, het Nationaal Park Drentsche Aa op een kwartier. In augustus kleurt de [paarse heide](/heide-drenthe) het hele gebied — dan is dit uitzicht op zijn mooist."]}, {"eyebrow": "Praktisch", "heading": "Prijzen en beschikbaarheid", "body": ["De prijs begint bij €165 per nacht voor de hele lodge, niet per persoon. In de schoolvakanties, rond feestdagen en in het hoogseizoen ligt hij hoger. Kosten voor eindschoonmaak en toeristenbelasting worden apart vermeld en komen bij de dagprijs. Boekingskosten rekenen wij niet, omdat u rechtstreeks bij de eigenaar boekt.", "Losse nachten verhuren wij niet. Er zijn twee wisseldagen — maandag en vrijdag — en daarmee drie vormen:"], "table": {"head": ["Vorm", "Aankomst", "Vertrek", "Nachten"], "rows": [["Weekend", "Vrijdag", "Zondag", "2"], ["Midweek", "Maandag", "Vrijdag", "4"], ["Week", "Maandag", "Zondag", "6"]], "note": "U geeft uw datums door en krijgt binnen 24 uur een persoonlijk voorstel met de volledige prijsopbouw: nachtprijs, schoonmaak en toeristenbelasting als aparte regels."}}, {"heading": "Praktische informatie", "body": [], "rows": [{"label": "Geschikt voor", "waarde": "1 – 4 personen"}, {"label": "Verhuurperiodes", "waarde": "Midweek (ma – vr), weekend (vr – zo) of week (ma – zo)"}, {"label": "Inchecken", "waarde": "Van 15:00 tot 21:00"}, {"label": "Uitchecken", "waarde": "Uiterlijk 11:00"}], "note": "Later aankomen dan 21:00 kan zonder extra kosten: de lodge heeft digitale sloten die tot middernacht werken, en er is geen receptie waar u zich hoeft te melden."}, {"heading": "Huisregels", "body": [], "marks": [{"icon": "nietRoken", "tekst": "Niet roken binnen"}, {"icon": "huisdier", "tekst": "Huisdieren toegestaan (€25)"}, {"icon": "geenFeest", "tekst": "Geen feesten of evenementen"}], "subheading": "Aanvullende huisregels", "dots": ["Tussen 22:00 en 08:00 uur geldt de nachtrust.", "Roken mag buiten, op de daarvoor bestemde plek.", "Alleen de directe omgeving van deze accommodatie is vuurwerkvrij."]}, {"heading": "Annuleren", "body": ["De volledige voorwaarden staan in de [algemene voorwaarden](/terms); dit is de samenvatting die er voor uw boeking toe doet."], "bullets": ["Tot 60 dagen voor aankomst krijgt u alles terug, op €25 administratiekosten na.", "Tussen 60 en 30 dagen voor aankomst 70%, tussen 30 en 14 dagen 50% en tussen 14 en 7 dagen 25%.", "Binnen 7 dagen voor aankomst is er geen restitutie.", "Omboeken kan tot 30 dagen voor aankomst, na goedkeuring en afhankelijk van beschikbaarheid. Daarvoor geldt een wijzigingsvergoeding van €25."]}, {"eyebrow": "De keuze", "heading": "De Heide of De Eik?", "body": ["Kort: De Heide heeft het uitzicht, De Eik heeft de buitensauna en de buitenkeuken. Verder zijn ze gelijkwaardig — beide voor vier personen, beide met een eigen hottub, beide volledig privé en op hetzelfde terrein.", "Gaat het u om stilte, vrij uitzicht en avonden met z''n tweeën, dan is deze pagina de juiste. Gaat het u om de sauna, buiten koken en een BBQ die de hele avond aan staat, [vergelijk dan met De Eik](/lodge-de-eik)."]}]'::jsonb,
       updated_at = now()
 where slug = 'lodge-de-heide';

-- ── lodge-de-eik ──────────────────────────────────────────
update landing_pages
   set sections = '[{"heading": "Wat er in de lodge zit", "body": ["De Eik is de ruimste van de twee. Dat merkt u vooral aan de hoogte: het is een omgebouwd gebouw met hoge plafonds, en dat maakt een verblijf met vier mensen aanzienlijk minder krap dan de vierkante meters doen vermoeden."], "bullets": ["Ruimte voor maximaal vier personen, verdeeld over twee slaapplekken.", "Volledig uitgeruste binnenkeuken: oven, kookplaat, koelkast, vaatwasser, servies en pannen.", "Buitenkeuken met BBQ onder de eiken, met de eettafel op hetzelfde terras.", "Eigen barrelsauna in de tuin, te stoken wanneer u wilt — geen reservering, geen tijdslot.", "Privé-hottub op het terras, het hele jaar door op 38 °C.", "Gratis snel WiFi en gratis parkeren op eigen terrein. Er is een laadstation aanwezig bij de lodge; het laden zelf is niet inbegrepen.", "Digitale sloten: inchecken kan tot middernacht zonder dat iemand op u wacht."]}, {"eyebrow": "Voorzieningen", "heading": "Wat er verder aanwezig is", "body": ["De voorzieningen waar gasten het vaakst naar vragen, hier op een rij. Ze zijn in beide lodges gelijk — het verschil tussen De Heide en De Eik zit in het uitzicht en de buitensauna, niet in wat er binnen staat."], "marksKaart": true, "marks": [{"icon": "wifi", "tekst": "Gratis snel WiFi"}, {"icon": "tv", "tekst": "Televisie"}, {"icon": "parkeren", "tekst": "Parkeren op eigen terrein"}, {"icon": "koelkast", "tekst": "Koelkast"}, {"icon": "koffie", "tekst": "Koffieapparaat"}, {"icon": "waterkoker", "tekst": "Waterkoker"}, {"icon": "verwarming", "tekst": "Verwarming"}]}, {"eyebrow": "Het onderscheid", "heading": "De buitenkeuken en de BBQ", "body": ["Buiten koken is iets anders dan een BBQ op het gras zetten. Hier staat een echte buitenkeuken: werkblad, BBQ en de ruimte om alles klaar te maken zonder tien keer naar binnen te lopen. Dat verandert hoe een avond verloopt — u staat niet om beurten binnen te koken terwijl de rest buiten zit, u bent er gewoon allemaal.", "De eiken erboven doen de rest. Ze houden de middagzon eruit, waardoor het terras ook in juli bruikbaar blijft, en ze maken het geluid zachter dan u van een terras gewend bent. Als het eten op is, staat de hottub op twee meter.", "En dan is er de barrelsauna. Die staat buiten, in de tuin naast het terras, en is alleen van de gasten van deze lodge. Geen reservering, geen tijdslot, geen mede-gasten — er is op het terrein geen gedeelde wellnessruimte. Van de sauna naar de hottub is tien stappen, en juist in de winter is dat het rondje waar gasten achteraf over vertellen. Wat hier niet staat is het vergezicht: [vergelijk met De Heide](/lodge-de-heide) als vrij uitzicht voor u zwaarder weegt."]}, {"eyebrow": "Voor wie", "heading": "Voor wie deze lodge is", "body": ["De Eik is de lodge voor gezelschappen die samen willen eten. Twee stellen die om beurten koken, een gezin met kinderen die de hele dag buiten zijn, of vier vrienden die vooral een lange tafel en een BBQ nodig hebben.", "Ook met z''n tweeën werkt hij, en dan vooral in het voor- en naseizoen: de ruimte is dan luxe in plaats van overmaat, en de sauna komt juist dan het best tot zijn recht. Zoekt u vooral stilte en een vrij vergezicht, dan is De Heide de betere keuze."]}, {"eyebrow": "De ligging", "heading": "Onder de eiken in Zeijen", "body": ["Zeijen is een van de brinkdorpen van Drenthe: een kerk, een brink, en daaromheen vrijwel meteen het veld. De lodge staat aan de rand daarvan, met de eiken eromheen en de Zeijerstrubben op loopafstand. Het centrum van Assen ligt op twintig minuten, wat ver genoeg is om er ''s avonds niets van te merken.", "Vanaf de deur beginnen de wandelroutes; er lopen meer dan 1.000 kilometer fietspaden door de omgeving en de e-bike laadt u op aan een buitenstopcontact bij de lodge. Wie hier komt voor de streek zelf, vindt de routes op onze pagina''s over [wandelroutes in Drenthe](/wandelroutes-drenthe) en [fietsen in Drenthe](/fietsen-in-drenthe)."]}, {"eyebrow": "Praktisch", "heading": "Prijzen en beschikbaarheid", "body": ["De prijs begint bij €165 per nacht voor de hele lodge, niet per persoon. In de schoolvakanties, rond feestdagen en in het hoogseizoen ligt hij hoger. Kosten voor eindschoonmaak en toeristenbelasting worden apart vermeld en komen bij de dagprijs. Boekingskosten rekenen wij niet, omdat u rechtstreeks bij de eigenaar boekt.", "Losse nachten verhuren wij niet. Er zijn twee wisseldagen — maandag en vrijdag — en daarmee drie vormen:"], "table": {"head": ["Vorm", "Aankomst", "Vertrek", "Nachten"], "rows": [["Weekend", "Vrijdag", "Zondag", "2"], ["Midweek", "Maandag", "Vrijdag", "4"], ["Week", "Maandag", "Zondag", "6"]], "note": "U geeft uw datums door en krijgt binnen 24 uur een persoonlijk voorstel met de volledige prijsopbouw: nachtprijs, schoonmaak en toeristenbelasting als aparte regels."}}, {"heading": "Praktische informatie", "body": [], "rows": [{"label": "Geschikt voor", "waarde": "1 – 4 personen"}, {"label": "Verhuurperiodes", "waarde": "Midweek (ma – vr), weekend (vr – zo) of week (ma – zo)"}, {"label": "Inchecken", "waarde": "Van 15:00 tot 21:00"}, {"label": "Uitchecken", "waarde": "Uiterlijk 11:00"}], "note": "Later aankomen dan 21:00 kan zonder extra kosten: de lodge heeft digitale sloten die tot middernacht werken, en er is geen receptie waar u zich hoeft te melden."}, {"heading": "Huisregels", "body": [], "marks": [{"icon": "nietRoken", "tekst": "Niet roken binnen"}, {"icon": "huisdier", "tekst": "Huisdieren toegestaan (€25)"}, {"icon": "geenFeest", "tekst": "Geen feesten of evenementen"}], "subheading": "Aanvullende huisregels", "dots": ["Tussen 22:00 en 08:00 uur geldt de nachtrust.", "Roken mag buiten, op de daarvoor bestemde plek.", "Alleen de directe omgeving van deze accommodatie is vuurwerkvrij."]}, {"heading": "Annuleren", "body": ["De volledige voorwaarden staan in de [algemene voorwaarden](/terms); dit is de samenvatting die er voor uw boeking toe doet."], "bullets": ["Tot 60 dagen voor aankomst krijgt u alles terug, op €25 administratiekosten na.", "Tussen 60 en 30 dagen voor aankomst 70%, tussen 30 en 14 dagen 50% en tussen 14 en 7 dagen 25%.", "Binnen 7 dagen voor aankomst is er geen restitutie.", "Omboeken kan tot 30 dagen voor aankomst, na goedkeuring en afhankelijk van beschikbaarheid. Daarvoor geldt een wijzigingsvergoeding van €25."]}, {"eyebrow": "De keuze", "heading": "De Eik of De Heide?", "body": ["Kort: De Eik heeft de buitensauna, de buitenkeuken en de ruimte, De Heide het panoramisch uitzicht. Verder zijn ze gelijkwaardig — beide voor vier personen, beide met een eigen hottub, beide volledig privé en op hetzelfde terrein.", "Weet u het nog niet, kies dan op wat u ''s avonds wilt doen. Buiten eten met de BBQ aan en daarna de sauna in: De Eik. Rustig naar de heide kijken met het water op 38 °C: De Heide."]}]'::jsonb,
       updated_at = now()
 where slug = 'lodge-de-eik';

-- ── Controle na afloop ────────────────────────────────────────────────────
-- Hoort 2 rijen te geven, allebei met true:
--
--   select slug,
--          sections::text like '%"marksKaart":true%'      as kaart_aan,
--          sections::text not like '%De inventaris%'      as eyebrow_weg
--     from landing_pages
--    where slug in ('lodge-de-heide', 'lodge-de-eik');
